var a=`1153-split-pea-soup`;var t=`world-1153`;var n=`CA`;var s=`northern-america`;var o=4;var r=478;var l={en:`Split Pea Soup`,ua:`Канадський гороховий суп`};var m={en:`Split Pea Soup is a dish from Canada prepared with yellow split peas, smoked ham, yellow onion, celery stalk. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Канадський гороховий суп, страва кухні країни Канада, яку готують із таких продуктів: жовтий колотий горох, копчена шинка, жовта цибуля, стебло селери. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var d=[{en:`Soak the dried beans in ample clean cold water for about 360 minutes, drain and discard the soaking water; cook fully in fresh water.`,ua:`Замочіть сухі бобові у достатній кількості чистої холодної води на приблизно 360 хвилин, злийте її й повністю зваріть у свіжій воді.`,t:[`soaking-legumes`],m:360,i:[[`yellow-split-peas`,400,`g`],[`water`,1e3,`ml`]]},{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 60 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 60 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:60,i:[[`smoked-ham`,350,`g`],[`water`,1550,`ml`],[`yellow-onion`,220,`g`],[`celery-stalk`,130,`g`],[`bay-leaf`,2,`leaf`]]},{en:`Add the listed ingredients to the pot. Keep at a gentle simmer for about 55 minutes, until tender and cooked through.`,ua:`Додайте зазначені складники до каструлі. Варіть за слабкого кипіння приблизно 55 хвилин до м’якості та готовності.`,t:[`simmering`],m:55,i:[[`carrot`,240,`g`],[`thyme`,4,`sprig`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`ground-black-pepper`,5,`g`]]}];var g={slug:a,id:t,country:`CA`,region:s,servings:4,minutes:478,title:l,text:m,steps:d};export{n as country,g as default,t as id,r as minutes,s as region,o as servings,a as slug,d as steps,m as text,l as title};